package dev.kuan.kuanperion.automation.supercraft;
import dev.kuan.kuanperion.automation.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;
public final class SupercraftServiceTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static void denied(Runnable r){try{r.run();throw new AssertionError("Expected invalid settings");}catch(IllegalArgumentException expected){}}
 public static void main(String[]args)throws Exception{var dir=Files.createTempDirectory("supercraft-service-");try{
  var path=dir.resolve("automation.json");var settings=AutomationSettingsStore.load(path);check(settings.supercraftPolicyValid()&&!settings.supercraftPolicy().configured()&&!settings.enabled(AutomationFeature.SUPERCRAFT),"no inherited/default craft authority");
  var policy=new SupercraftPolicy(SupercraftTaskTest.POLICY,60);settings.setSupercraftPolicy(policy);settings.setEnabled(AutomationFeature.SUPERCRAFT,true);check(AutomationSettingsStore.load(path).supercraftPolicy().equals(policy),"explicit complete recipe/consumption policy external and restart safe");
  var f=new SupercraftTaskTest.Fake();var session=new AutomationSession(new AutomationCoordinator(),f::context,()->f.pauses++,()->f.stops++);var allowed=new AtomicBoolean(false);var notices=new ArrayList<StashService.Notice>();var s=new SupercraftService(settings,session,new InventoryReceipts(),new CursorReceipts(),f,allowed::get,notices::add);
  s.tick(0);check(f.requests==0&&!s.active(),"settings GUI prevents startup data/commands");check(s.manualRequest(0)&&s.pending(),"explicit UI click queues one bounded request");s.tick(SupercraftTaskTest.S);check(f.requests==0,"queue never replaces own settings screen");allowed.set(true);s.tick(2*SupercraftTaskTest.S);check(s.active()&&f.requests==1&&session.holdsFarming(),"UI close starts exactly one authorized task");s.suspend(3*SupercraftTaskTest.S);check(!s.active()&&!s.pending()&&!s.autoEnabled()&&f.stops==1,"active Jerry stop cancels exact original hold");
  s.setEnabled(true);byte[] before=Files.readAllBytes(path);s.suspend(4*SupercraftTaskTest.S);s.tick(200*SupercraftTaskTest.S);check(!s.active()&&!s.autoEnabled()&&Arrays.equals(before,Files.readAllBytes(path)),"idle suspension cannot silently rearm or rewrite preferences");
  check(s.manualRequest(201*SupercraftTaskTest.S),"explicit manual request after suspension");allowed.set(false);s.tick(232*SupercraftTaskTest.S);check(!s.pending()&&f.requests==1,"stale queued click expires, cannot unexpectedly run after later UI close");
  s.setEnabled(true);allowed.set(true);s.tick(233*SupercraftTaskTest.S);check(s.active()&&f.requests==2,"explicit enable permits automatic exact-batch request");allowed.set(false);s.tick(234*SupercraftTaskTest.S);check(!s.active()&&!s.autoEnabled(),"opening non-owned screen cancels active task rather than replacing it");
  // A real service success uses exact item removals/output and a fresh server cursor before any hold release.
  var successFile=dir.resolve("success.json");var prefs=AutomationSettingsStore.load(successFile);prefs.setSupercraftPolicy(policy);prefs.setEnabled(AutomationFeature.SUPERCRAFT,true);var h=new SupercraftTaskTest.H();var menuAllowed=new AtomicBoolean(true);var complete=new ArrayList<StashService.Notice>();var service=new SupercraftService(prefs,h.session,h.receipts,h.cursor,h.f,menuAllowed::get,complete::add);
  service.tick(0);check(service.active()&&h.f.commands==1,"automatic data and typed recipe under root");h.f.show();menuAllowed.set(false);h.session.poll(SupercraftTaskTest.S);service.tick(SupercraftTaskTest.S);check(service.active()&&h.f.crafts==1,"owned recipe screen is allowed, not mistaken for manual UI");
  h.now=SupercraftTaskTest.S;h.result(true,true);h.session.poll(2*SupercraftTaskTest.S);service.tick(2*SupercraftTaskTest.S);check(service.active()&&h.f.closes==0,"applied output first, no early original hold release");h.session.poll(3*SupercraftTaskTest.S);service.tick(3*SupercraftTaskTest.S);check(!service.active()&&h.f.stops==0&&!h.session.active()&&h.f.closes==1&&complete.size()==1&&!complete.getFirst().warning(),"one successful batch closes exact menu and releases valid original Farm");
  menuAllowed.set(true);service.tick(4*SupercraftTaskTest.S);check(!service.active()&&h.f.requests==1,"cooldown prevents consecutive unbounded batches");
  check(service.manualRequest(25*SupercraftTaskTest.S),"queue pending with auto enabled");service.cancel(26*SupercraftTaskTest.S);service.tick(200*SupercraftTaskTest.S);check(!service.active()&&!service.pending()&&!service.autoEnabled(),"stopping queued work cannot immediately auto-run it again");
  service.setEnabled(true);Files.writeString(successFile,Files.readString(successFile)+" ");try{service.setEnabled(false);throw new AssertionError("expected conflicting write");}catch(java.io.IOException expected){}check(!service.autoEnabled(),"a failed disable write must still stop automatic dispatch in memory");
  for(String bad:List.of("{\"intervalSeconds\":0}","{\"outputCount\":\"2\"}","{\"onlyWhileFarming\":1}","{\"outputs\":[\"A\",\"A\"]}","{\"recipe\":{\"outputId\":\"A\",\"outputPerCraft\":1,\"stackLimit\":64,\"inputs\":{\"WHEAT\":1.5}}}")){
   Files.writeString(path,"{\"schemaVersion\":1,\"features\":{\"supercraft\":true},\"supercraft\":"+bad+"}");var invalid=AutomationSettingsStore.load(path);check(!invalid.supercraftPolicyValid()&&!invalid.supercraftPolicy().configured(),"malformed explicit consent denied: "+bad);
  }
  Files.writeString(path,"{\"schemaVersion\":1,\"future\":7,\"supercraft\":{\"future\":true,\"recipe\":{\"future\":true}}}");var preserve=AutomationSettingsStore.load(path);preserve.setSupercraftPolicy(policy);String saved=Files.readString(path);check(saved.contains("\"future\": 7")&&saved.contains("\"future\": true"),"unknown root/section/recipe fields preserved");
  Files.writeString(path,"{\"schemaVersion\":9}");var future=AutomationSettingsStore.load(path);check(!future.supercraftPolicyValid(),"future settings never run");
  System.out.println("SupercraftServiceTest: PASS (external strict recipe/caps, off defaults, deferred expiring UI request, demand-only dispatch, screen priority, active/idle Jerry suspension, no stale retry)");
 }finally{try(var walk=Files.walk(dir)){for(var p:walk.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}}
}
